<?php
$date = static function (?string $value): string { if ($value === null) { return '—'; } try { return (new DateTimeImmutable($value))->format('d/m/Y H:i'); } catch (Throwable) { return $value; } };
?>
<section class="admin-reports" aria-labelledby="admin-actions-title"><header class="admin-reports__hero"><div><p class="eyebrow">Auditoria administrativa</p><h1 id="admin-actions-title">Ações de moderação</h1><p>Registro imutável das sanções e remoções realizadas por administradores.</p></div><a class="button button--secondary" href="/admin/denuncias">Fila de denúncias</a></header>
<?php if ($actions->items === []): ?><section class="reports-empty"><h2>Nenhuma ação registrada.</h2><p>Resoluções sem sanção não aparecem nesta trilha.</p></section><?php else: ?><div class="audit-list" role="list"><?php foreach ($actions->items as $action): ?><article class="audit-card" role="listitem"><header><span class="report-status report-status--resolved"><?= e($action->type->label()) ?></span><time><?= e($date($action->createdAt)) ?></time></header><h2><?= e($action->targetDisplayName ?? 'Usuário indisponível') ?></h2><?php if ($action->targetUsername !== null): ?><p>@<?= e($action->targetUsername) ?></p><?php endif; ?><dl><div><dt>Administrador</dt><dd><?= $action->performedByUsername !== null ? '@' . e($action->performedByUsername) : 'Conta removida' ?></dd></div><?php if ($action->reportId !== null): ?><div><dt>Denúncia</dt><dd><a href="/admin/denuncias/<?= $action->reportId ?>">#<?= $action->reportId ?></a></dd></div><?php endif; ?><?php if ($action->effectiveUntil !== null): ?><div><dt>Vigência</dt><dd><?= e($date($action->effectiveUntil)) ?></dd></div><?php endif; ?></dl></article><?php endforeach; ?></div><?php endif; ?>
<?php if ($actions->totalPages() > 1): ?><nav class="pagination" aria-label="Paginação da auditoria"><?php if ($actions->page > 1): ?><a href="/admin/acoes?page=<?= $actions->page - 1 ?>">← Anterior</a><?php else: ?><span aria-disabled="true">← Anterior</span><?php endif; ?><strong>Página <?= $actions->page ?> de <?= $actions->totalPages() ?></strong><?php if ($actions->page < $actions->totalPages()): ?><a href="/admin/acoes?page=<?= $actions->page + 1 ?>">Próxima →</a><?php else: ?><span aria-disabled="true">Próxima →</span><?php endif; ?></nav><?php endif; ?></section>
